fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // All input arrays must have the same length
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n);
    assert_eq!(conds_1.len(), n);
    assert_eq!(conds_2.len(), n);

    // Prepare the output vector
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let v1 = vals_1[i];
        let v2 = vals_2[i];
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // At least one of c1 or c2 is guaranteed true by precondition
        let result = if c1 {
            if c2 {
                // both true: integer average
                (v1 + v2) / 2
            } else {
                // only first true
                v1
            }
        } else {
            // only second true
            v2
        };

        avgs.push(result);
    }
}